# Load grids from session
import os, re

def load_grids():
    d = os.environ.get('RLM_SESSION_DIR', '')
    if not d:
        print("No RLM_SESSION_DIR")
        return {}
    try:
        t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read()
    except:
        return {}

    G = {}

    # Pattern: "Demo pair N input (HxW):" and "Demo pair N output (HxW):" and "Test input (HxW):"
    pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'
    for m in re.finditer(pattern, t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = t[m.end():].split('\n')[:h]
        valid = all(len(r) == w and all(x.isdigit() for x in r) for r in rows)
        if k not in G and valid:
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load_grids()
print("Grids loaded:", sorted(G.keys()))
for k, g in sorted(G.items()):
    print(f"--- {k}: {len(g)}x{len(g[0]) if g else 0} ---")

